bool PageStubDispatch::Accept(
    Page* impl,
    mojo::Message* message) {
  switch (message->header()->name) {
    case internal::kPage_OnSuggestRequestCreated_Name: {

      DCHECK(message->is_serialized());
      internal::Page_OnSuggestRequestCreated_Params_Data* params =
          reinterpret_cast<internal::Page_OnSuggestRequestCreated_Params_Data*>(
              message->mutable_payload());
      
      bool success = true;
      RequestPtr p_request{};
      Page_OnSuggestRequestCreated_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadRequest(&p_request))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Page::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->OnSuggestRequestCreated(
std::move(p_request));
      return true;
    }
    case internal::kPage_OnSuggestRequestStarted_Name: {

      DCHECK(message->is_serialized());
      internal::Page_OnSuggestRequestStarted_Params_Data* params =
          reinterpret_cast<internal::Page_OnSuggestRequestStarted_Params_Data*>(
              message->mutable_payload());
      
      bool success = true;
      RequestPtr p_request{};
      Page_OnSuggestRequestStarted_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadRequest(&p_request))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Page::Name_, 1, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->OnSuggestRequestStarted(
std::move(p_request));
      return true;
    }
    case internal::kPage_OnSuggestRequestCompleted_Name: {

      DCHECK(message->is_serialized());
      internal::Page_OnSuggestRequestCompleted_Params_Data* params =
          reinterpret_cast<internal::Page_OnSuggestRequestCompleted_Params_Data*>(
              message->mutable_payload());
      
      bool success = true;
      RequestPtr p_request{};
      Page_OnSuggestRequestCompleted_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadRequest(&p_request))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            Page::Name_, 2, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->OnSuggestRequestCompleted(
std::move(p_request));
      return true;
    }
  }
  return false;
}

