// static
bool StructTraits<::suggest_internals::mojom::Request::DataView, ::suggest_internals::mojom::RequestPtr>::Read(
    ::suggest_internals::mojom::Request::DataView input,
    ::suggest_internals::mojom::RequestPtr* output) {
  bool success = true;
  ::suggest_internals::mojom::RequestPtr result(::suggest_internals::mojom::Request::New());
  
      if (success && !input.ReadId(&result->id))
        success = false;
      if (success && !input.ReadUrl(&result->url))
        success = false;
      if (success && !input.ReadData(&result->data))
        success = false;
      if (success && !input.ReadStatus(&result->status))
        success = false;
      if (success && !input.ReadStartTime(&result->start_time))
        success = false;
      if (success && !input.ReadEndTime(&result->end_time))
        success = false;
      if (success && !input.ReadResponse(&result->response))
        success = false;
  *output = std::move(result);
  return success;
}

