PageHandlerAsyncWaiter::PageHandlerAsyncWaiter(
    PageHandler* proxy) : proxy_(proxy) {}

PageHandlerAsyncWaiter::~PageHandlerAsyncWaiter() = default;

void PageHandlerAsyncWaiter::HardcodeResponse(
    const std::string& response, RequestPtr* out_request) {
  base::RunLoop loop;
  proxy_->HardcodeResponse(std::move(response),
      base::BindOnce(
          [](base::RunLoop* loop,
             RequestPtr* out_request
,
             RequestPtr request) {*out_request = std::move(request);
            loop->Quit();
          },
          &loop,
          out_request));
  loop.Run();
}

RequestPtr PageHandlerAsyncWaiter::HardcodeResponse(
    const std::string& response) {
  RequestPtr async_wait_result;
  HardcodeResponse(std::move(response),&async_wait_result);
  return async_wait_result;
}




